// -----------------------------------------------------------------------------
// Minimal SmartThings Cloud API client (uses the Node.js built-in fetch).
//
// The SmartThings Cloud API (https://api.smartthings.com/v1) is authenticated
// with a bearer token, which comes from either:
//   - an OAuth2 session (see ./oauth.js): refreshed before it expires, and
//     once more when the API still answers 401;
//   - a Personal Access Token (PAT) generated by the user at
//     https://account.smartthings.com/tokens — a static token.
//
//   - GET  /devices                    -> list of devices (paginated)
//   - GET  /devices/{id}/status        -> full status (components -> capabilities)
//   - POST /devices/{id}/commands      -> send one or more commands
//
// A 401 that survives the refresh means the token is invalid or expired
// (SmartThings PATs created since late 2024 expire after 24h): the error is
// surfaced so the integration can report it in the Gladys UI.
// -----------------------------------------------------------------------------

import { createLogger } from '@gladysassistant/integration-sdk';

import { SMARTTHINGS_ENDPOINT } from '../constants.js';

const logger = createLogger({ name: 'smartthings' });

const REQUEST_TIMEOUT_MS = 15000;

export class SmartThingsClient {
  constructor(baseUrl = SMARTTHINGS_ENDPOINT) {
    this.baseUrl = baseUrl.replace(/\/+$/, '');
    this.auth = null;
  }

  isConfigured() {
    return this.auth !== null;
  }

  /**
   * Use a Personal Access Token for every request.
   * @param {string} token SmartThings Personal Access Token
   */
  setToken(token) {
    this.auth = token ? { getAccessToken: async () => token } : null;
  }

  /**
   * Use an OAuth2 session for every request.
   * @param {{ getAccessToken: () => Promise<string>, refresh: (rejectedToken: string) => Promise<string> }} session
   */
  setOAuthSession(session) {
    this.auth = session || null;
  }

  clearToken() {
    this.auth = null;
  }

  /**
   * List every device visible to the token, following the API pagination.
   * @returns {Promise<Array>} the raw SmartThings device objects
   */
  async listDevices() {
    const devices = [];
    let path = 'devices';
    // Follow `_links.next` until the API stops returning one (guarded against
    // a runaway loop).
    for (let page = 0; path && page < 50; page += 1) {
      const response = await this.#authenticatedRequest(path);
      devices.push(...(response.items || []));
      path = this.#nextPagePath(response);
    }
    logger.debug(`${devices.length} devices loaded`);
    return devices;
  }

  /**
   * Fetch the live status of one device (all components / capabilities).
   * @param {string} deviceId SmartThings device id
   * @returns {Promise<object>} the device status ({ components: { main: {...} } })
   */
  async getDeviceStatus(deviceId) {
    return this.#authenticatedRequest(`devices/${encodeURIComponent(deviceId)}/status`);
  }

  /**
   * Send commands to a device.
   * @param {string} deviceId SmartThings device id
   * @param {Array<object>} commands array of { component, capability, command, arguments }
   */
  async sendCommands(deviceId, commands) {
    return this.#authenticatedRequest(`devices/${encodeURIComponent(deviceId)}/commands`, {
      method: 'POST',
      body: JSON.stringify({ commands }),
      contentType: 'application/json',
    });
  }

  /**
   * Turn an absolute or relative `_links.next.href` into a path relative to the
   * API base, so it can be fed back to #fetchJson.
   */
  #nextPagePath(response) {
    const next = response && response._links && response._links.next && response._links.next.href;
    if (!next) {
      return null;
    }
    // The API may return an absolute URL; keep only the part after the base.
    if (next.startsWith('http')) {
      const url = new URL(next);
      return `${url.pathname.replace(/^\/v1\//, '')}${url.search}`;
    }
    return next.replace(/^\/?(v1\/)?/, '');
  }

  async #authenticatedRequest(path, options = {}) {
    if (!this.isConfigured()) {
      throw new Error('SmartThings is not configured (connect an account or fill in a token)');
    }
    const auth = this.auth;
    const token = await auth.getAccessToken();
    try {
      return await this.#fetchJson(path, {
        ...options,
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch (err) {
      // OAuth2: a token rejected before its announced expiry (revoked, clock
      // drift) gets one refresh and one retry. A PAT cannot be refreshed.
      if (err.status !== 401 || !auth.refresh) {
        throw err;
      }
      logger.warn(`SmartThings rejected the access token on ${path}: refreshing it`);
      const fresh = await auth.refresh(token);
      return this.#fetchJson(path, {
        ...options,
        headers: { Authorization: `Bearer ${fresh}` },
      });
    }
  }

  async #fetchJson(path, { method = 'GET', headers = {}, body, contentType }) {
    const response = await fetch(`${this.baseUrl}/${path}`, {
      method,
      headers: {
        Accept: 'application/json',
        ...(contentType ? { 'Content-Type': contentType } : {}),
        ...headers,
      },
      body,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });
    if (!response.ok) {
      const error = new Error(
        `SmartThings request failed: ${method} ${path} -> HTTP ${response.status}`,
      );
      error.status = response.status;
      throw error;
    }
    // Command endpoints may answer with an empty body.
    const text = await response.text();
    return text ? JSON.parse(text) : {};
  }
}
